local __ok, __err = xpcall(function()
  local code = lx_inflate(lx_b64(table.concat(LX_MAIN)))
  local fn, cerr = loadstring(code, "=Lexushub")
  if not fn then error("compile error: " .. tostring(cerr)) end
  code = nil
  local comp, iy
