  local rets = table.pack(fn(function()
    comp = comp or lx_inflate(lx_b64(table.concat(LX_COMP)))
    return comp
  end, function()
    iy = iy or lx_inflate(lx_b64(table.concat(LX_IY)))
    return iy
  end, FUCKLEXS_KEY_SOURCE))
  pcall(function() LX_LOADING:Destroy() end)
  return table.unpack(rets, 1, rets.n)
end, function(e) return tostring(e) .. "\n" .. debug.traceback() end)
